acceptance:
# morph: subset transaction
D=/tmp/morph/parse-turn-p27; mkdir -p $D; S=$(date +%s)-$$; L=$D/acc-$S.log
cp src/scout/parseTurn.ts $D/0-$S.ts 2>/dev/null
(
 set -e
 export NO_COLOR=1 CI=1
P=$PWD/probe/parse-turn; rm -rf $P; mkdir -p $P; trap 'rm -rf $P' EXIT
cat > $P/guard.mjs <<'MORPH_GUARD_EOF'
// MorphV2 guard: the layer rules of docs/CONVENTIONS.md and the test-file rules, checked on
// the TypeScript syntax tree. Inlined into every acceptance by decks/tools/build.py.
//   node guard.mjs src [file,file,...]                   every .ts under src/, or only these
//   node guard.mjs helpers <file> <name,name,...>        the stub module: node:* only, exports
//   node guard.mjs tests <file> <min> <max> [lits.json]  one test file; lits = strings it must hold
import ts from "typescript";
import fs from "node:fs";
import path from "node:path";

const bad = [];

// which internal layers a layer may import; "*" = any; unknown dirs are reported
const LAYERS = {
  cards: [], wait: [],
  response: ["cards"], store: ["cards"], compiler: ["cards"], language: ["cards"],
  contour: ["cards"], git: ["cards"], acceptance: ["cards", "wait", "compiler"],
  processor: ["cards", "wait", "compiler"], planner: ["cards", "contour", "language"],
  builder: ["cards", "language"],
  primer: ["cards", "git", "store", "language"],
  // P13a: the seed reads language's profiles (and, from P13b, git's ownership) (docs/TASK_P13a_scout.md §4)
  // P13b: the round loop builds the processor's Request and Message (compiler's types) (docs/TASK_P13b_scout.md §4)
  scout: ["cards", "processor", "wait", "primer", "language", "git", "compiler"],
  // P14a: obligations from the record need language's naming and profiles (docs/TASK_P14_reviewer.md §4)
  // P14b: the mutant runs go through acceptance's runner and snapshot (docs/TASK_P14b_reviewer.md §4)
  reviewer: ["cards", "contour", "primer", "scout", "git", "language", "acceptance"],
  runloop: ["cards", "wait", "store", "compiler", "response", "acceptance", "language",
    "git", "processor"],
  // P11b2: the detached batch commands (morph submit / morph collect), the processor layer's second Component
  batches: ["cards", "wait", "compiler", "processor"],
  // P17: the debt commands (morph card / morph accept, issue #8) read the deck through cards, run the card's acceptance
  // through acceptance and commit through git (docs/TASK_P17_debt.md §4)
  // P24b: the group accept (issue #16) writes archived answers parsed by compiler's parseAnswer, as the run does
  // (docs/TASK_P24b_group.md §4)
  debt: ["cards", "compiler", "acceptance", "git"],
  // P18: morph init (issue #9) copies the template folders into a new project: no other layer (docs/TASK_P18_template.md §4)
  scaffold: [],
  // P22a: morph gate (issue #13) plays a deck's stubs and references in a scratch clone: the deck through cards, the
  // acceptances through acceptance, the clone and its commits through git, the file:line patterns through language
  // (docs/TASK_P22a_gate.md §4)
  // P22b: the gate's mutants go through the reviewer's Plan Mutants and Run Mutants; Check Identity hashes a cut with
  // node:crypto (docs/TASK_P22b_mutants.md §4)
  gate: ["cards", "acceptance", "git", "language", "reviewer"],
  cli: "*",
};
const ROOT_FILES = new Set(["src/index.ts"]);
const SHELL = new Set(["acceptance", "git"]);          // node:child_process
const NET = new Set(["processor"]);                    // fetch, WebSocket, XMLHttpRequest
const CONSOLE = new Set(["cli"]);                      // console, process.exit
const PROCESS = new Set(["cli", "processor", "acceptance"]);
const NO_CLOCK = new Set(["cards", "compiler", "response", "language", "contour", "planner", "builder", "batches", "primer",
  "scout", "reviewer", "debt", "scaffold", "gate"]);
// P12a: the one file of src/primer that turns the clock parameter deps.now() into an ISO string (docs/TASK_P12_primer.md §4)
// P13b: the one file of src/scout that turns deps.now() into the session id and createdAt (docs/TASK_P13b_scout.md §4)
const CLOCK_FORMATTERS = new Set(["src/primer/primerCommand.ts", "src/scout/scoutCommand.ts"]);
const YAML = new Set(["contour"]);
// P3: the acceptance gets the child's environment as a parameter (docs/TASK_P3_acceptance.md §4)
const NO_ENV = new Set(["acceptance", "processor", "git", "batches", "primer", "scout", "reviewer", "debt", "scaffold", "gate"]);
// P4: the one file of a NO_ENV layer that may read process.env (Read Registry, docs/TASK_P4_processor.md §4)
const ENV_READERS = new Set(["src/processor/registry.ts"]);
// P6: the one file of src/git that spawns (Run Git, docs/TASK_P6_git.md §4); git takes the env whole
const GIT_SPAWNER = "src/git/run.ts";
// P7: the binary's entry is src/cli.ts (package.json bin dist/cli.js), layer cli; it alone touches
// process (env, argv, cwd, stdout, exitCode) and the wall clock: src/cli/* gets them as parameters
// (docs/TASK_P7_cli.md §4)
const CLI_ENTRY = "src/cli.ts";
// P8: language is pure data and pure functions; of the Node modules only node:path (posix) is allowed
// (docs/TASK_P8_language.md §4)
// P9: contour reads text it is given: no Node module at all, and the package yaml only in Parse Document
// (src/contour/load.ts) (docs/TASK_P9_contour.md §4)
// P10a: planner is pure like language: of the Node modules only node:path (docs/TASK_P10a_planner.md §4)
// P10b: builder is pure the same way (docs/TASK_P10b_builder.md §4)
// P13a: scout reaches the file system only through its ScoutFs parameter: of the Node modules only node:path
// (docs/TASK_P13a_scout.md §4; P13b adds the one node:fs adapter file)
const NODE_ONLY = { language: new Set(["node:path"]), contour: new Set(), planner: new Set(["node:path"]),
  builder: new Set(["node:path"]), scout: new Set(["node:path"]), reviewer: new Set(),
  debt: new Set(["node:fs", "node:path"]), scaffold: new Set(["node:fs", "node:path", "node:url"]),
  gate: new Set(["node:fs", "node:os", "node:path", "node:crypto"]) };
// P18: scaffold reads the template folders and writes the new project (node:fs, node:path) and finds the package root from
// its own module file (node:url's fileURLToPath of import.meta.url); it spawns nothing (docs/TASK_P18_template.md §4)
// P17: debt reads the deck file, the card's files and the run archive (node:fs, node:path); it spawns only through
// acceptance's runAcceptance and git's gitOk (docs/TASK_P17_debt.md §4)
// P14a: the reviewer's checks are pure functions of git's outputs, the record and the texts they are given: no Node
// module at all (docs/TASK_P14_reviewer.md §4; P14b adds the review command's I/O file)
// P13b: the two I/O files of src/scout, the commands `morph scout` (the node:fs ScoutFs adapter, git ls-files, the
// scout.json write, the question's sha256) and `morph plan --from-scout` (reads scout.json, writes the deck); every other
// scout file stays pure (docs/TASK_P13b_scout.md §4)
// P14b: the one I/O file of src/reviewer, `morph review` (the record, the map and scout.json read, the review written);
// Run Mutants writes and restores through acceptance's snapshot, so it imports no Node module (docs/TASK_P14b_reviewer.md §4)
const NODE_FILES = { "src/scout/scoutCommand.ts": new Set(["node:fs", "node:crypto"]),
  "src/scout/planFromScout.ts": new Set(["node:fs"]),
  "src/reviewer/reviewCommand.ts": new Set(["node:fs", "node:path"]) };
const YAML_FILE = "src/contour/load.ts";

function parse(file) {
  return ts.createSourceFile(file, fs.readFileSync(file, "utf8"), ts.ScriptTarget.Latest, true,
    ts.ScriptKind.TS);
}
function line(sf, node) {
  return sf.getLineAndCharacterOfPosition(node.getStart(sf)).line + 1;
}
function report(sf, node, rule) {
  bad.push(`guard: ${sf.fileName}:${line(sf, node)} ${rule}`);
}
function walk(node, fn) {
  fn(node);
  ts.forEachChild(node, (child) => walk(child, fn));
}
// an identifier that refers to a value binding (not a property name, a type, a declared name)
function isValueRef(node) {
  const p = node.parent;
  if (!p) return false;
  if (ts.isPropertyAccessExpression(p) && p.name === node) return false;
  if ((ts.isPropertyAssignment(p) || ts.isPropertyDeclaration(p) || ts.isPropertySignature(p) ||
       ts.isMethodDeclaration(p) || ts.isMethodSignature(p) || ts.isGetAccessor(p) ||
       ts.isSetAccessor(p) || ts.isEnumMember(p)) && p.name === node) return false;
  if (ts.isTypeReferenceNode(p) || ts.isQualifiedName(p) || ts.isTypeQueryNode(p)) return false;
  if ((ts.isParameter(p) || ts.isVariableDeclaration(p) || ts.isFunctionDeclaration(p) ||
       ts.isBindingElement(p)) && p.name === node) return false;
  if (ts.isImportSpecifier(p) || ts.isExportSpecifier(p) || ts.isImportClause(p)) return false;
  if (ts.isLabeledStatement(p) || ts.isBreakOrContinueStatement(p)) return false;
  return true;
}
function tsFiles(dir) {
  const out = [];
  if (!fs.existsSync(dir)) return out;
  for (const e of fs.readdirSync(dir, { withFileTypes: true })) {
    const f = path.join(dir, e.name);
    if (e.isDirectory()) out.push(...tsFiles(f));
    else if (f.endsWith(".ts")) out.push(f);
  }
  return out.sort();
}
function moduleSpecifiers(sf) {
  const out = [];
  walk(sf, (node) => {
    if ((ts.isImportDeclaration(node) || (ts.isExportDeclaration(node) && node.moduleSpecifier)) &&
        ts.isStringLiteralLike(node.moduleSpecifier)) out.push([node, node.moduleSpecifier.text]);
    if (ts.isCallExpression(node) && node.expression.kind === ts.SyntaxKind.ImportKeyword)
      report(sf, node, "dynamic import");
  });
  return out;
}
function layerOf(rel) {
  if (rel === CLI_ENTRY) return "cli";
  const parts = rel.split("/");
  return parts.length >= 3 && parts[0] === "src" ? parts[1] : null;
}

function checkSrc(files) {
  for (const file of files ?? tsFiles("src")) {
    const sf = parse(file);
    const rel = file.split(path.sep).join("/");
    const layer = layerOf(rel);
    if (layer === null && !ROOT_FILES.has(rel)) { bad.push(`guard: ${rel} is not under a layer directory`); continue; }
    if (layer !== null && !(layer in LAYERS)) { bad.push(`guard: ${rel} is in an unknown layer "${layer}"`); continue; }
    const allowed = layer === null ? [] : LAYERS[layer];
    for (const [node, spec] of moduleSpecifiers(sf)) {
      if (spec.startsWith("node:")) {
        if (layer in NODE_ONLY && !NODE_ONLY[layer].has(spec) && !(NODE_FILES[rel]?.has(spec)))
          report(sf, node, `${spec} in the pure layer ${layer} (only ${[...NODE_ONLY[layer]].join(", ") || "none"})`);
        if (spec === "node:child_process" && !SHELL.has(layer))
          report(sf, node, `node:child_process outside src/acceptance and src/git`);
        if (spec === "node:child_process" && layer === "git" && rel !== GIT_SPAWNER)
          report(sf, node, `node:child_process in ${rel} (only ${GIT_SPAWNER} spawns git)`);
        continue;
      }
      if (spec === "yaml") {
        if (!YAML.has(layer)) report(sf, node, `"yaml" outside src/contour`);
        else if (rel !== YAML_FILE) report(sf, node, `"yaml" in ${rel} (only ${YAML_FILE} parses text)`);
        continue;
      }
      if (!spec.startsWith("./") && !spec.startsWith("../")) { report(sf, node, `package import "${spec}" (node:* only)`); continue; }
      const target = path.posix.normalize(path.posix.join(path.posix.dirname(rel), spec));
      const tl = layerOf(target);
      if (tl === null) { if (!ROOT_FILES.has(target)) report(sf, node, `import of "${spec}" outside src/<layer>/`); continue; }
      if (tl !== layer && allowed !== "*" && !allowed.includes(tl))
        report(sf, node, `layer ${layer ?? "src"} imports layer ${tl} (allowed: ${allowed.join(", ") || "none"})`);
    }
    walk(sf, (node) => {
      if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
      if (ts.isIdentifier(node) && isValueRef(node)) {
        const n = node.text;
        if (["fetch", "WebSocket", "XMLHttpRequest"].includes(n) && !NET.has(layer))
          report(sf, node, `global ${n} outside src/processor`);
        if (n === "console" && !CONSOLE.has(layer)) report(sf, node, "console outside src/cli");
        if (n === "process" && !PROCESS.has(layer)) report(sf, node, "process outside src/cli, src/processor, src/acceptance");
        if ((n === "process" || n === "console") && layer === "cli" && rel !== CLI_ENTRY)
          report(sf, node, `${n} in ${rel} (only ${CLI_ENTRY} touches it; env, cwd, clock and io are parameters)`);
        if (n === "Date" && NO_CLOCK.has(layer) && !CLOCK_FORMATTERS.has(rel)) report(sf, node, `Date in the deterministic layer ${layer}`);
        if (n === "Math" && node.parent && ts.isPropertyAccessExpression(node.parent) &&
            node.parent.name.text === "random") report(sf, node, "Math.random");
      }
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "exit" && !CONSOLE.has(layer))
        report(sf, node, "process.exit outside src/cli");
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "exit" && rel === CLI_ENTRY)
        report(sf, node, `process.exit in ${CLI_ENTRY} (set process.exitCode: exit cuts a piped stdout)`);
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "Date" && node.name.text === "now" && layer === "cli" && rel !== CLI_ENTRY)
        report(sf, node, `Date.now in ${rel} (the clock is the parameter now)`);
      if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression) &&
          node.expression.text === "process" && node.name.text === "env" && NO_ENV.has(layer) &&
          !ENV_READERS.has(rel))
        report(sf, node, `process.env in src/${layer} (the environment is a parameter)`);
    });
  }
}

function checkHelpers(file, names) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const sf = parse(file);
  for (const [node, spec] of moduleSpecifiers(sf))
    if (!spec.startsWith("node:")) report(sf, node, `helpers import "${spec}" (node:* only)`);
  const exported = new Set();
  walk(sf, (node) => {
    if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
    const mods = ts.canHaveModifiers(node) ? ts.getModifiers(node) ?? [] : [];
    if (!mods.some((m) => m.kind === ts.SyntaxKind.ExportKeyword)) return;
    if ((ts.isFunctionDeclaration(node) || ts.isInterfaceDeclaration(node) ||
         ts.isTypeAliasDeclaration(node) || ts.isClassDeclaration(node)) && node.name)
      exported.add(node.name.text);
    if (ts.isVariableStatement(node))
      for (const d of node.declarationList.declarations) if (ts.isIdentifier(d.name)) exported.add(d.name.text);
  });
  for (const n of names) if (!exported.has(n)) bad.push(`guard: ${file} does not export ${n}`);
}

function checkTest(file, min, max, lits) {
  if (!fs.existsSync(file)) { bad.push(`guard: ${file} missing`); return; }
  const sf = parse(file);
  const text = sf.getFullText();
  let count = 0;
  for (const [node, spec] of moduleSpecifiers(sf))
    if (spec !== "vitest" && !spec.startsWith("node:") && !spec.startsWith("./") && !spec.startsWith("../"))
      report(sf, node, `import of a package "${spec}" (vitest, node:* and relative paths only)`);
  walk(sf, (node) => {
    if (node.kind === ts.SyntaxKind.AnyKeyword) report(sf, node, "explicit any");
    if (ts.isCallExpression(node) && ts.isIdentifier(node.expression) &&
        (node.expression.text === "test" || node.expression.text === "it")) count += 1;
    if (ts.isPropertyAccessExpression(node) && ts.isIdentifier(node.expression)) {
      const o = node.expression.text, p = node.name.text;
      if (["test", "it", "describe"].includes(o) && ["skip", "only", "todo", "fails"].includes(p))
        report(sf, node, `${o}.${p}`);
      if (o === "vi" && ["stubGlobal", "useFakeTimers", "mock", "doMock"].includes(p))
        report(sf, node, `vi.${p} (stubs come from tests/helpers.ts)`);
    }
    if (ts.isIdentifier(node) && isValueRef(node) &&
        ["setTimeout", "setInterval", "setImmediate"].includes(node.text))
      report(sf, node, `${node.text} (real timers are not used under tests/; use fakeClock)`);
    const declared = (ts.isFunctionDeclaration(node) || ts.isVariableDeclaration(node) ||
      ts.isClassDeclaration(node)) && node.name && ts.isIdentifier(node.name) ? node.name.text : null;
    if (declared && (declared === "fetch" || /^[Ff]ake/.test(declared)))
      report(sf, node, `own stub "${declared}" (stubs come from tests/helpers.ts)`);
  });
  if (count < min || count > max)
    bad.push(`guard: ${file} has ${count} test/it calls, expected ${min}..${max}`);
  for (const lit of lits) if (!text.includes(lit)) bad.push(`guard: ${file} does not mention the example literal ${JSON.stringify(lit)}`);
}

const [mode, a, b, c, d] = process.argv.slice(2);
if (mode === "src") checkSrc(a ? a.split(",").filter(Boolean) : null);
else if (mode === "helpers") checkHelpers(a, (b ?? "").split(",").filter(Boolean));
else if (mode === "tests") checkTest(a, Number(b), Number(c), d ? JSON.parse(fs.readFileSync(d, "utf8")) : []);
else bad.push(`guard: unknown mode ${mode}`);
for (const x of bad) console.log(x);
process.exit(bad.length ? 1 : 0);
MORPH_GUARD_EOF
cat > $P/probe.config.mts <<'MORPH_CONF_EOF'
import { defineConfig } from "vitest/config";
import { fileURLToPath } from "node:url";
export default defineConfig({
  root: fileURLToPath(new URL("../..", import.meta.url)),
  test: { environment: "node", include: ["probe/parse-turn/**/*.probe.ts"],
    setupFiles: ["tests/setup.ts"], chaiConfig: { truncateThreshold: 200 } },
});
MORPH_CONF_EOF
cat > $P/tsconfig.card.json <<'MORPH_TSCONF_EOF'
{
  "extends": "../../tsconfig.json",
  "include": [
    "../../src",
    "../../tests",
    "./*.probe.ts"
  ]
}
MORPH_TSCONF_EOF
cat > $P/firstdiff.mjs <<'MORPH_FIRSTDIFF_EOF'
// MorphV2 first-difference locator: reads a vitest log and, for every failed comparison whose two
// sides vitest printed in full ("Expected: ..." / "Received: ..." lines, or a "- Expected" / "+ Received"
// diff block), prints where the two first differ, with 40 chars of context on each side. The assertion
// line itself is cut at truncateThreshold, so a one-word difference deep in a long string reads as two
// identical sides (P9b, output-directive-judge: three retries on "the file" / "a file").
// Inlined into the acceptances by decks/tools/build.py (from P9c on).
//   node firstdiff.mjs <vitest log>
import fs from "node:fs";

const lines = fs.readFileSync(process.argv[2], "utf8").split("\n");
const pairs = [];
for (let i = 0; i < lines.length; i++) {
  if (lines[i].startsWith("Expected: ") && (lines[i + 1] ?? "").startsWith("Received: ")) {
    pairs.push([lines[i].slice(10), lines[i + 1].slice(10)]);
    continue;
  }
  if (lines[i] !== "- Expected" || lines[i + 1] !== "+ Received") continue;
  // the diff block: "  x" both sides, "- x" expected only, "+ x" received only, "" an empty common line;
  // it ends at the source pointer " ❯ ..." or a rule line
  const e = [], r = [];
  let j = i + 3;
  for (; j < lines.length && !lines[j].startsWith(" ❯") && !lines[j].startsWith("⎯"); j++) {
    const l = lines[j];
    if (l.startsWith("-")) e.push(l.slice(2));
    else if (l.startsWith("+")) r.push(l.slice(2));
    else { e.push(l.slice(2)); r.push(l.slice(2)); }
  }
  while (e.length && r.length && e[e.length - 1] === "" && r[r.length - 1] === "") { e.pop(); r.pop(); }
  pairs.push([e.join("\n"), r.join("\n")]);
  i = j;
}
let shown = 0;
for (const [e, r] of pairs) {
  if (e === r || shown >= 6) continue;
  let k = 0;
  while (k < e.length && k < r.length && e[k] === r[k]) k++;
  const line = e.slice(0, k).split("\n").length;
  const at = (s) => JSON.stringify((k > 40 ? "..." : "") + s.slice(Math.max(0, k - 40), k + 40));
  console.log(`first difference at char ${k} (line ${line}) of ${e.length}/${r.length}: expected ${at(e)} received ${at(r)}`);
  shown++;
}
MORPH_FIRSTDIFF_EOF
cat > $P/parse-turn.probe.ts <<'MORPH_PROBE_EOF'
// P27 probe for parse-turn by docs/TASK_P27_scout.md §2.2 (src/scout/parseTurn.ts) — issue #21 items 1, 3, 4, 9:
// a bare JSON answer, repeated and several action lines, slash-delimited GREP, the first balanced object.
// Record Parse Turn examples 5 (changed), 7, 8, 9; examples 1 and 4 green on main by design.
import { test, expect } from "vitest";
import { parseTurn } from "../../src/scout/parseTurn.js";

const NO_ACTION = "no action: one line must start with READ, GREP, LIST or ANSWER";

test("Parse Turn example 1: unchanged reads (green on main)", () => {
  expect(parseTurn("I will check the cage first.\nREAD src/scout/cagePath.ts")).toStrictEqual({
    kind: "action", action: { kind: "read", path: "src/scout/cagePath.ts", from: null, to: null } });
});

test("Parse Turn example 4: unchanged ANSWER (green on main)", () => {
  const turn = parseTurn("ANSWER {\"context_slice\": [\"c.ts\"], \"reasoning\": \"r\", \"targets\": [\"a.ts\", \"b.ts\"]}");
  expect(JSON.stringify(turn)).toBe("{\"kind\":\"answer\",\"answer\":{\"targets\":[\"a.ts\",\"b.ts\"],\"context_slice\":[\"c.ts\"],\"reasoning\":\"r\"}}");
});

test("Parse Turn example 5: the eleven malformed turns of the record, in order", () => {
  const inputs: (string | null)[] = [null, " \n\t", "The change is in src/a.ts", "Read src/a.ts", "READX a", "{\"files\": [\"a\"]}",
    "READ", "READ a.ts 9-3", "READ a.ts 0-3", "GREP ( -- src", "GREP"];
  const reasons = ["empty turn", "empty turn", NO_ACTION, NO_ACTION, NO_ACTION, NO_ACTION, "READ needs a path",
    "READ: bad line range 9-3", "READ: bad line range 0-3", "GREP: invalid pattern /(/", "GREP needs a pattern"];
  expect(inputs.map((t) => parseTurn(t))).toStrictEqual(reasons.map((reason) => ({ kind: "malformed", reason })));
});

test("Parse Turn example 7: a bare or fenced JSON answer", () => {
  expect(parseTurn("{\"targets\": [\"a.ts\"], \"reasoning\": \"r\"}")).toStrictEqual({
    kind: "answer", answer: { targets: ["a.ts"], context_slice: [], reasoning: "r" } });
  expect(parseTurn("Here it is:\n```json\n{\"targets\": [\"a.ts\"], \"context_slice\": [\"b.ts\"]}\n```")).toStrictEqual({
    kind: "answer", answer: { targets: ["a.ts"], context_slice: ["b.ts"], reasoning: "" } });
  expect(parseTurn("{\"targets\": []}")).toStrictEqual({ kind: "malformed", reason: "ANSWER: targets must be a non-empty list of paths" });
  expect(parseTurn("{\"targets\": [\"a.ts\"], \"reasoning\": \"the \"x\" key\"}")).toStrictEqual({ kind: "malformed", reason: NO_ACTION });
});

test("Parse Turn example 8: repeated and several action lines", () => {
  const grep = parseTurn("GREP DoneWait -- .\nGREP DoneWait -- .");
  expect(JSON.stringify(grep)).toBe("{\"kind\":\"action\",\"action\":{\"kind\":\"grep\",\"pattern\":\"DoneWait\",\"path\":\".\"}}");
  const list = parseTurn("LIST a\nLIST b\nLIST a\n  LIST b  ");
